// Calculate which fact to show based on the week of the year
// This rotates through the entire list, one fact per week
export function getFactForCurrentWeek(): Fact {
  // Get the current week number (1-52)
  const now = new Date();
  const startOfYear = new Date(now.getFullYear(), 0, 1);
  const daysSinceStart = Math.floor((now.getTime() - startOfYear.getTime()) / (1000 * 60 * 60 * 24));
  const weekNumber = Math.floor(daysSinceStart / 7);
  
  // Use modulo to cycle through all facts
  // Add year offset so facts change every year too
  const yearOffset = now.getFullYear() * 7;
  const factIndex = (weekNumber + yearOffset) % facts.length;
  
  return facts[factIndex];
}

// Get fact by ID (for "show me another" feature)
export function getFactByIndex(index: number): Fact {
  return facts[index % facts.length];
}
